package compile

// Rendered views (Designs/SddGraph DD-1, DD-2): the graph is the source of
// truth; phase markdown is a projection regenerated by compile, never
// hand-edited, never parsed back. Every generated file carries a marker
// naming the graph and the regenerating command, and the renderer REFUSES to
// overwrite any existing file that lacks the marker — that one rule is both
// the transition guard (a v1 hand-authored phase doc is never clobbered by
// accident; conversion takes it over explicitly, task 2.5) and the
// frozen-view refusal for hand-authored documents (a completed v1 phase's
// doc, anchored by a frozen review, is exactly such a file). Generated views
// have their own frozen-view rule (DD-2, task 4.1): a view rendered while
// every node in it was CLOSED (GREEN + covered by a passing frozen full
// review gate, the D-0022 completion-grade predicate) carries the
// frozen-view marker, and a later render that would CHANGE such a file is
// refused — byte-identical re-renders stay no-ops, so compile remains
// runnable on a completed plan. A legitimately reopened phase (a finding
// demoted a node after its gate recorded) requires removing the frozen view
// explicitly; the refusal names that escape.
//
// The plan README is treated differently from phase docs: its prose sections
// (Overview, Non-Goals, ...) and frontmatter are plan identity the graph
// does not hold, so the renderer performs exactly two surgical edits —
// initializing empty phases[] or refreshing statuses of proven graph-owned
// entries, and
// upserting one marker-delimited `## Graph View` section — and otherwise
// preserves the file byte-for-byte. Non-rendered (v1) phase entries retain
// their ownership and bytes; merging their membership is conversion's job.

import (
	"fmt"
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strings"
	"sync"
	"time"

	"github.com/danweinerdev/claude-sdd-planner/v2/internal/graph/model"
	"github.com/danweinerdev/claude-sdd-planner/v2/internal/graph/states"
	"github.com/danweinerdev/claude-sdd-planner/v2/internal/rules"
	istore "github.com/danweinerdev/claude-sdd-planner/v2/internal/store"
	"github.com/danweinerdev/claude-sdd-planner/v2/internal/vcs"
)

// frozenViewMarker marks a generated view rendered while every node in it
// was closed. Its presence turns content-changing regeneration into a
// refusal (DD-2's frozen-view invariant).
const frozenViewMarker = "<!-- FROZEN VIEW — every node in this phase is closed: GREEN and covered by a passing frozen full review gate. This projection is history; a render that would change it is refused. -->"

// revExistsMemoRepo memoizes RevisionExists per revision, local to one
// renderViews call — production's vcs.EnableMemoization is opt-in and
// process-lifetime, but renderViews must not depend on it: preflightViews
// and the write pass both render every closed phase and would otherwise
// probe the same checkpoint revision twice per phase, and sibling phases
// sharing one checkpoint would probe it once per phase instead of once per
// revision. Every other Repo method delegates straight through.
type revExistsMemoRepo struct {
	vcs.Repo
	mu    sync.Mutex
	cache map[string]revExistsResult
}

type revExistsResult struct {
	exists bool
	err    error
}

func (m *revExistsMemoRepo) RevisionExists(rev string) (bool, error) {
	m.mu.Lock()
	defer m.mu.Unlock()
	if v, ok := m.cache[rev]; ok {
		return v.exists, v.err
	}
	exists, err := m.Repo.RevisionExists(rev)
	if m.cache == nil {
		m.cache = map[string]revExistsResult{}
	}
	m.cache[rev] = revExistsResult{exists, err}
	return exists, err
}

// now is the render-time clock every date stamp in this file reads,
// exposed as a package-level variable so a test can advance it across a
// simulated day boundary without a real wall-clock wait — the only way to
// distinguish "reads a stable placeholder" from "reads the wall clock
// directly" within a single test process. Production code never assigns
// it.
var now = time.Now

// viewMarker identifies a generated view. Its presence is the renderer's
// permission to overwrite; its absence on an existing target is a refusal.
// The prefix is owned by internal/rules (the validator keys SDD163's
// projection exemption on it), so emission and recognition cannot drift.
func viewMarker(plan string) string {
	return fmt.Sprintf("%s%s-Graph.json. Regenerate with `sdd compile --plan %s`. Edits here are overwritten. -->", rules.GeneratedViewMarkerPrefix, plan, plan)
}

// graphViewBegin/End delimit the README's upserted section. Owned by
// internal/rules: lifecycle normalization strips exactly these delimiters,
// so a frozen phase review's README pin survives the upsert.
const (
	graphViewBegin = rules.GraphViewBegin
	graphViewEnd   = rules.GraphViewEnd
)

// phaseGroup is one rendered phase: its ordinal, label, and nodes in
// declaration order.
type phaseGroup struct {
	Ordinal int
	Label   string
	Title   string
	Doc     string
	Nodes   []*model.Node
}

// PhaseGroup is the exported projection of phaseGroup a caller needs to
// locate a rendered phase doc's owning nodes (`sdd phase complete` on a
// graph plan) without duplicating the grouping the renderer already does.
type PhaseGroup struct {
	Ordinal int
	Title   string
	Doc     string
	Nodes   []*model.Node
}

// GroupPhases is the exported form of groupPhases.
func GroupPhases(g *model.Graph, plan string) []PhaseGroup {
	groups := groupPhases(g, plan)
	out := make([]PhaseGroup, len(groups))
	for i, ph := range groups {
		out[i] = PhaseGroup{Ordinal: ph.Ordinal, Title: ph.Title, Doc: ph.Doc, Nodes: ph.Nodes}
	}
	return out
}

// groupPhases buckets nodes by their presentation label (DD-9: `phase` is a
// grouping consumed only by views), ordered by label with unlabeled nodes
// last as "Ungrouped".
func groupPhases(g *model.Graph, plan string) []phaseGroup {
	byLabel := map[string][]*model.Node{}
	var labels []string
	for i := range g.Nodes {
		n := &g.Nodes[i]
		if _, seen := byLabel[n.Phase]; !seen {
			labels = append(labels, n.Phase)
		}
		byLabel[n.Phase] = append(byLabel[n.Phase], n)
	}
	sort.SliceStable(labels, func(i, j int) bool {
		if (labels[i] == "") != (labels[j] == "") {
			return labels[j] == "" // unlabeled last
		}
		return labels[i] < labels[j]
	})
	var out []phaseGroup
	for i, label := range labels {
		title := label
		if title == "" {
			title = "Ungrouped"
		}
		ordinal := i + 1
		out = append(out, phaseGroup{
			Ordinal: ordinal,
			Label:   label,
			Title:   phaseTitle(title),
			Doc:     fmt.Sprintf("%02d-%s.md", ordinal, viewSlug(title)),
			Nodes:   byLabel[label],
		})
	}
	return out
}

var slugCleanRe = regexp.MustCompile(`[^A-Za-z0-9]+`)
var slugLeadingOrdinalRe = regexp.MustCompile(`^\d+-`)
var titleWordSplitRe = regexp.MustCompile(`[-_]+`)

// viewSlug turns a phase label into a filename component, dropping a leading
// `NN-` so a label like "01-core" does not double-number the doc.
func viewSlug(label string) string {
	s := slugLeadingOrdinalRe.ReplaceAllString(label, "")
	s = slugCleanRe.ReplaceAllString(s, "-")
	s = strings.Trim(s, "-")
	if s == "" {
		s = "phase"
	}
	return s
}

// phaseTitle derives a human title from a raw phase label: strips a leading
// numeric prefix (`01-hermetic-git` -> `hermetic-git`), splits on `-`/`_`,
// and title-cases each word. The label itself (and the doc file stem
// viewSlug derives from it) is untouched — only the rendered title changes,
// so regenerating an existing plan does not move files.
func phaseTitle(label string) string {
	s := slugLeadingOrdinalRe.ReplaceAllString(label, "")
	if s == "" {
		return label
	}
	words := titleWordSplitRe.Split(s, -1)
	var out []string
	for _, w := range words {
		if w == "" {
			continue
		}
		out = append(out, strings.ToUpper(w[:1])+strings.ToLower(w[1:]))
	}
	if len(out) == 0 {
		return label
	}
	return strings.Join(out, " ")
}

// phaseStatus projects a group's frontmatter status: `complete` only when
// every node is CLOSED (the derived D-0022 predicate — never a stored flag,
// never hand-checked), `in-progress` once any node carries a claim or
// observation, else `planned`.
func phaseStatus(nodes []*model.Node, closed map[string]bool) string {
	if allClosed(nodes, closed) {
		return "complete"
	}
	for _, n := range nodes {
		if n.Claim != nil || n.Verification != nil {
			return "in-progress"
		}
	}
	return "planned"
}

// allClosed reports whether every node in the group derives closed.
func allClosed(nodes []*model.Node, closed map[string]bool) bool {
	if len(nodes) == 0 {
		return false
	}
	for _, n := range nodes {
		if !closed[n.ID] {
			return false
		}
	}
	return true
}

// preflightViews dry-runs every render target before anything is written:
// both refusal rules (non-generated file in a target's place, frozen view
// whose content would change) fire here, BEFORE the graph write, leaving
// nothing half-done. repo is the caller's already-resolved evidence repo
// (shared with the write pass so an identity probe memoized here is not
// repeated there).
func preflightViews(root, plan, repoRoot string, repo vcs.Repo, g *model.Graph, st map[string]states.NodeState, closed map[string]bool) error {
	planDir := filepath.Join(root, "Plans", plan)
	for _, ph := range groupPhases(g, plan) {
		path := filepath.Join(planDir, ph.Doc)
		content, err := renderPhaseDoc(planDir, plan, g, ph, "{DATE}", "{DATE}", repoRoot, repo, st, closed)
		if err != nil {
			return err
		}
		if _, _, err := planWrite(path, content, plan); err != nil {
			return err
		}
	}
	_, _, err := planReadmeUpdate(planDir, plan, groupPhases(g, plan), closed)
	return err
}

// resolveEvidenceRepo resolves the vcs.Repo the phase evidence's identity
// recheck probes, or nil when repoRoot is empty (no resolved target
// repository at render time) or repoRoot is under no supported VCS — the
// honest "no recheck ran" case identityRecheckLine renders rather than
// fabricating a check. A detection failure that IS operational (the git
// executable itself unavailable, ...) still resolves to vcs.Unavailable,
// which correctly reports vcs.ErrOperational once actually probed. The
// returned repo memoizes RevisionExists per revision for the lifetime of
// this Repo value — callers that render more than once (preflight, then
// write) must resolve it ONCE and share the result so the memo covers both
// passes.
func resolveEvidenceRepo(repoRoot string) vcs.Repo {
	if repoRoot == "" {
		return nil
	}
	repo := detectVCS(repoRoot)
	if repo.Kind() == vcs.None {
		return nil
	}
	return &revExistsMemoRepo{Repo: repo}
}

// detectVCS is a test seam over vcs.Detect: a test counting how many times
// resolveEvidenceRepo itself is invoked (e.g. across compile.Run's preflight
// and write-pass render sharing one resolved repo) wraps this rather than
// mocking RevisionExists, which only proves the memo works WITHIN one
// resolved repo, not that resolution itself happened once. Production code
// always uses vcs.Detect.
var detectVCS = vcs.Detect

// RenderViews writes the phase views and updates the README projection.
// Exported so callers outside a staged-proposal compile (e.g. `sdd plan
// complete` / `sdd phase complete` on a graph plan, which have nothing to
// stage) can refresh the same rendered views `sdd compile` produces,
// without duplicating the renderer. repoRoot is the resolved target
// repository, used only to derive the Repository label the plan/phase
// completion evidence sections carry (SDD072). The evidence repo is
// resolved once here; a caller that already resolved one (e.g. Run, which
// shares it with an earlier preflight over the preview graph) should call
// renderViewsWithRepo directly instead, so the identity probe is memoized
// across that call too rather than probed again per compile.
func RenderViews(root, plan, repoRoot string, g *model.Graph, st map[string]states.NodeState, closed map[string]bool) ([]string, error) {
	return renderViewsWithRepo(root, plan, repoRoot, resolveEvidenceRepo(repoRoot), g, st, closed)
}

// renderViews writes the phase views and updates the README projection,
// resolving its own evidence repo. Test-only entry point within the
// package; production callers with a repo already resolved use
// renderViewsWithRepo so the identity probe is not resolved (and therefore
// not potentially re-probed) twice.
func renderViews(root, plan, repoRoot string, g *model.Graph, st map[string]states.NodeState, closed map[string]bool) ([]string, error) {
	return renderViewsWithRepo(root, plan, repoRoot, resolveEvidenceRepo(repoRoot), g, st, closed)
}

// renderViewsWithRepo writes the phase views and updates the README
// projection using a caller-resolved evidence repo — shared across an
// earlier preflight and this write pass (or across multiple renders in one
// compile) so a revision's identity probe is memoized once, not once per
// resolution.
func renderViewsWithRepo(root, plan, repoRoot string, repo vcs.Repo, g *model.Graph, st map[string]states.NodeState, closed map[string]bool) ([]string, error) {
	planDir := filepath.Join(root, "Plans", plan)
	groups := groupPhases(g, plan)
	if err := preflightViews(root, plan, repoRoot, repo, g, st, closed); err != nil {
		return nil, err
	}

	// Phase files are written FIRST: planReadmeUpdate's status/title
	// reconciliation (refreshReadmePhaseStatuses) reads each phase doc from
	// disk to confirm it carries the generated-view marker before touching
	// its README entry — ownership it can only ever see once the doc
	// exists. Reading the README before this loop (and writing it after,
	// compare-and-swap against that read) still keeps a just-created
	// marker from retroactively authorizing a takeover of an existing
	// hand-authored entry: writeView's own frozen/marker refusals gate
	// each phase file independently, before any of them lands.
	var written []string
	for _, ph := range groups {
		path := filepath.Join(planDir, ph.Doc)
		// Dates stay templated here; writeView fills them with stability
		// rules (existing created preserved, updated stamped on change).
		content, err := renderPhaseDoc(planDir, plan, g, ph, "{DATE}", "{DATE}", repoRoot, repo, st, closed)
		if err != nil {
			return nil, err
		}
		wrote, err := writeView(path, content, plan)
		if err != nil {
			return nil, err
		}
		if wrote {
			written = append(written, path)
		}
	}

	readmeBefore, err := os.ReadFile(filepath.Join(planDir, "README.md"))
	if err != nil {
		return nil, err
	}
	readme, readmeChanged, err := planReadmeUpdate(planDir, plan, groups, closed)
	if err != nil {
		return nil, err
	}

	if readmeChanged {
		if err := istore.WriteAtomicExpecting(filepath.Join(planDir, "README.md"), readme, istore.Digest(string(readmeBefore))); err != nil {
			return nil, err
		}
		written = append(written, filepath.Join(planDir, "README.md"))
	}
	return written, nil
}

// PathForView is exported for tests and callers that need to know where a
// phase group renders.
func PathForView(root, plan, doc string) string {
	return filepath.Join(root, "Plans", plan, doc)
}
